let file = """{"version":3,"file":"outputAssetUtil-B_PHmavR.js","names":["$t","$t","$t","$t","$t","$t","$t"],"sources":["../../src/renderer/core/layout/transform/useTransformState.ts","../../src/components/ui/search-input/AsyncSearchInput.vue","../../src/components/ui/search-input/AsyncSearchInput.vue","../../src/platform/assets/utils/assetSortUtils.ts","../../src/platform/assets/composables/useModelTypes.ts","../../src/platform/assets/components/UploadModelConfirmation.vue","../../src/platform/assets/components/UploadModelConfirmation.vue","../../src/platform/assets/components/VideoHelpDialog.vue","../../src/platform/assets/components/VideoHelpDialog.vue","../../src/platform/assets/components/UploadModelFooter.vue","../../src/platform/assets/components/UploadModelFooter.vue","../../src/platform/assets/components/UploadModelProgress.vue","../../src/platform/assets/components/UploadModelProgress.vue","../../src/platform/assets/components/UploadModelUrlInput.vue","../../src/platform/assets/components/UploadModelUrlInput.vue","../../src/platform/assets/importSources/civitaiImportSource.ts","../../src/platform/assets/importSources/huggingfaceImportSource.ts","../../src/platform/assets/utils/importSourceUtil.ts","../../src/platform/assets/composables/useUploadModelWizard.ts","../../src/platform/assets/components/UploadModelDialog.vue","../../src/platform/assets/components/UploadModelDialog.vue","../../src/platform/assets/components/UploadModelDialogHeader.vue","../../src/platform/assets/components/UploadModelUpgradeModalBody.vue","../../src/platform/assets/components/UploadModelUpgradeModalFooter.vue","../../src/platform/assets/components/UploadModelUpgradeModalFooter.vue","../../src/platform/assets/components/UploadModelUpgradeModal.vue","../../src/platform/assets/components/UploadModelUpgradeModal.vue","../../src/platform/assets/components/UploadModelUpgradeModalHeader.vue","../../src/platform/assets/composables/useModelUpload.ts","../../src/platform/assets/composables/useAssetFilterOptions.ts","../../src/platform/assets/utils/assetFilterUtils.ts","../../src/platform/assets/utils/outputKeyUtil.ts","../../src/platform/assets/utils/outputAssetUtil.ts"],"sourcesContent":["/**\n * Composable for managing transform state synchronized with LiteGraph canvas\n *\n * This composable is a critical part of the hybrid rendering architecture that\n * allows Vue components to render in perfect alignment with LiteGraph's canvas.\n *\n * ## Core Concept\n *\n * LiteGraph uses a canvas for rendering connections, grid, and handling interactions.\n * Vue components need to render nodes on top of this canvas. The challenge is\n * synchronizing the coordinate systems:\n *\n * - LiteGraph: Uses canvas coordinates with its own transform matrix\n * - Vue/DOM: Uses screen coordinates with CSS transforms\n *\n * ## Solution: Transform Container Pattern\n *\n * Instead of transforming individual nodes (O(n) complexity), we:\n * 1. Mirror LiteGraph's transform matrix to a single CSS container\n * 2. Place all Vue nodes as children with simple absolute positioning\n * 3. Achieve O(1) transform updates regardless of node count\n *\n * ## Coordinate Systems\n *\n * - **Canvas coordinates**: LiteGraph's internal coordinate system\n * - **Screen coordinates**: Browser's viewport coordinate system\n * - **Transform sync**: camera.x/y/z mirrors canvas.ds.offset/scale\n *\n * ## Performance Benefits\n *\n * - GPU acceleration via CSS transforms\n * - No layout thrashing (only transform changes)\n * - Efficient viewport culling calculations\n * - Scales to 1000+ nodes while maintaining 60 FPS\n *\n * @example\n * ```typescript\n * const { camera, transformStyle, screenToCanvas } = useTransformState()\n *\n * // In template\n * <div :style=\"transformStyle\">\n *   <NodeComponent\n *     v-for=\"node in nodes\"\n *     :style=\"{ left: node.x + 'px', top: node.y + 'px' }\"\n *   />\n * </div>\n *\n * // Convert coordinates\n * const canvasPos = screenToCanvas({ x: clientX, y: clientY })\n * ```\n */\nimport { computed, reactive, readonly } from 'vue'\n\nimport type { LGraphCanvas } from '@/lib/litegraph/src/litegraph'\nimport { createSharedComposable } from '@vueuse/core'\n\ninterface Point {\n  x: number\n  y: number\n}\n\ninterface Camera {\n  x: number\n  y: number\n  z: number // scale/zoom\n}\n\nfunction useTransformStateIndividual() {\n  // Reactive state mirroring LiteGraph's canvas transform\n  const camera = reactive<Camera>({\n    x: 0,\n    y: 0,\n    z: 1\n  })\n\n  // Computed transform string for CSS\n  const transformStyle = computed(() => ({\n    // Match LiteGraph DragAndScale.toCanvasContext():\n    // ctx.scale(scale); ctx.translate(offset)\n    // CSS applies right-to-left, so \"scale() translate()\" -> translate first, then scale\n    // Effective mapping: screen = (canvas + offset) * scale\n    // Using the 3D versions of scale and translate can provide a smoother experience\n    // when dealing with a large number of nodes.\n    transform: `scale3d(${camera.z}, ${camera.z}, ${camera.z}) translate3d(${camera.x}px, ${camera.y}px, 0)`,\n    transformOrigin: '0 0'\n  }))\n\n  /**\n   * Synchronizes Vue's reactive camera state with LiteGraph's canvas transform\n   *\n   * Called every frame via RAF to ensure Vue components stay aligned with canvas.\n   * This is the heart of the hybrid rendering system - it bridges the gap between\n   * LiteGraph's canvas transforms and Vue's reactive system.\n   *\n   * @param canvas - LiteGraph canvas instance with DragAndScale (ds) transform state\n   */\n  function syncWithCanvas(canvas: LGraphCanvas) {\n    // Mirror LiteGraph's transform state to Vue's reactive state\n    // ds.offset = pan offset, ds.scale = zoom level\n    camera.x = canvas.ds.offset[0]\n    camera.y = canvas.ds.offset[1]\n    camera.z = canvas.ds.scale || 1\n  }\n\n  /**\n   * Converts screen coordinates to canvas coordinates\n   *\n   * Inverse of the pane's own `transformStyle`. Useful for hit testing and\n   * converting mouse events back to canvas space.\n   *\n   * Formula: canvas = screen / scale - offset\n   *\n   * @param point - Point in screen coordinate system\n   * @returns Point in canvas coordinate system\n   */\n  const screenToCanvas = (point: Point): Point => {\n    return {\n      x: point.x / camera.z - camera.x,\n      y: point.y / camera.z - camera.y\n    }\n  }\n\n  return {\n    camera: readonly(camera),\n    transformStyle,\n    syncWithCanvas,\n    screenToCanvas\n  }\n}\n\nexport const useTransformState = createSharedComposable(\n  useTransformStateIndividual\n)\n","<script setup lang=\"ts\">\nimport { refDebounced } from '@vueuse/core'\nimport { nextTick, onMounted, ref, toRef, toValue, watch } from 'vue'\nimport type { HTMLAttributes, MaybeRefOrGetter } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  searcher = async () => {},\n  updateKey,\n  autofocus = false,\n  debounceMs = 250,\n  debounceMaxWaitMs = 1000,\n  class: customClass\n} = defineProps<{\n  searcher?: (\n    query: string,\n    onCleanup: (cleanupFn: () => void) => void\n  ) => Promise<void>\n  updateKey?: MaybeRefOrGetter<unknown>\n  autofocus?: boolean\n  debounceMs?: number\n  debounceMaxWaitMs?: number\n  class?: HTMLAttributes['class']\n}>()\nconst emit = defineEmits<{\n  enter: [event: KeyboardEvent]\n}>()\n\nconst searchQuery = defineModel<string>({ default: '' })\n\n// The native `autofocus` attribute only fires on initial page load, not when the\n// input is mounted dynamically (e.g. inside a modal), so focus it explicitly.\nconst inputRef = ref<HTMLInputElement>()\nonMounted(() => {\n  if (!autofocus) return\n  void nextTick(() => inputRef.value?.focus())\n})\n\ndefineExpose({\n  focus: () => inputRef.value?.focus()\n})\n\nconst isQuerying = ref(false)\nconst debouncedSearchQuery = refDebounced(searchQuery, debounceMs, {\n  maxWait: debounceMaxWaitMs\n})\nwatch(searchQuery, (value) => {\n  isQuerying.value = value !== debouncedSearchQuery.value\n})\nconst updateKeyRef = toRef(() => toValue(updateKey))\n\nwatch(\n  [debouncedSearchQuery, updateKeyRef],\n  (_, __, onCleanup) => {\n    let isCleanup = false\n    let cleanupFn: undefined | (() => void)\n    onCleanup(() => {\n      isCleanup = true\n      cleanupFn?.()\n    })\n\n    searcher(debouncedSearchQuery.value, (cb) => (cleanupFn = cb))\n      .catch((error) => {\n        console.error('[AsyncSearchInput] searcher failed', error)\n      })\n      .finally(() => {\n        if (!isCleanup) isQuerying.value = false\n      })\n  },\n  { immediate: true }\n)\n\nfunction handleFocus(event: FocusEvent) {\n  const target = event.target\n  if (target instanceof HTMLInputElement) {\n    target.select()\n  }\n}\n\nfunction handleKeydownEnter(event: KeyboardEvent) {\n  if (event.isComposing) return\n  emit('enter', event)\n}\n</script>\n\n<template>\n  <label\n    :class=\"\n      cn(\n        'group',\n        'rounded-lg bg-secondary-background transition-all duration-150',\n        'flex flex-1 items-center',\n        'border-0 text-base-foreground',\n        'focus-within:ring focus-within:ring-border-default/80',\n        customClass\n      )\n    \"\n  >\n    <i\n      :class=\"\n        cn(\n          'ml-2 size-4 shrink-0 transition-colors duration-150',\n          isQuerying\n            ? 'icon-[lucide--loader-circle] animate-spin'\n            : 'icon-[lucide--search]',\n          searchQuery?.trim() !== ''\n            ? 'text-base-foreground'\n            : 'text-muted-foreground group-focus-within:text-base-foreground group-hover:text-base-foreground'\n        )\n      \"\n    />\n    <input\n      ref=\"inputRef\"\n      v-model=\"searchQuery\"\n      type=\"text\"\n      class=\"mx-2 my-1.5 h-5 w-full min-w-0 border-0 bg-transparent ring-0 outline-0\"\n      :placeholder=\"$t('g.searchPlaceholder', { subject: '' })\"\n      :autofocus\n      @focus=\"handleFocus\"\n      @keydown.enter=\"handleKeydownEnter\"\n    />\n    <button\n      v-if=\"searchQuery.trim().length > 0\"\n      class=\"m-0 flex shrink-0 items-center justify-center border-0 bg-transparent p-0 pr-3 pl-1 text-muted-foreground ring-0 outline-0 transition-all duration-150 hover:scale-108 hover:text-base-foreground\"\n      :aria-label=\"$t('g.clear')\"\n      @click=\"searchQuery = ''\"\n    >\n      <i :class=\"cn('icon-[lucide--delete] size-4 cursor-pointer')\" />\n    </button>\n  </label>\n</template>\n","<script setup lang=\"ts\">\nimport { refDebounced } from '@vueuse/core'\nimport { nextTick, onMounted, ref, toRef, toValue, watch } from 'vue'\nimport type { HTMLAttributes, MaybeRefOrGetter } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  searcher = async () => {},\n  updateKey,\n  autofocus = false,\n  debounceMs = 250,\n  debounceMaxWaitMs = 1000,\n  class: customClass\n} = defineProps<{\n  searcher?: (\n    query: string,\n    onCleanup: (cleanupFn: () => void) => void\n  ) => Promise<void>\n  updateKey?: MaybeRefOrGetter<unknown>\n  autofocus?: boolean\n  debounceMs?: number\n  debounceMaxWaitMs?: number\n  class?: HTMLAttributes['class']\n}>()\nconst emit = defineEmits<{\n  enter: [event: KeyboardEvent]\n}>()\n\nconst searchQuery = defineModel<string>({ default: '' })\n\n// The native `autofocus` attribute only fires on initial page load, not when the\n// input is mounted dynamically (e.g. inside a modal), so focus it explicitly.\nconst inputRef = ref<HTMLInputElement>()\nonMounted(() => {\n  if (!autofocus) return\n  void nextTick(() => inputRef.value?.focus())\n})\n\ndefineExpose({\n  focus: () => inputRef.value?.focus()\n})\n\nconst isQuerying = ref(false)\nconst debouncedSearchQuery = refDebounced(searchQuery, debounceMs, {\n  maxWait: debounceMaxWaitMs\n})\nwatch(searchQuery, (value) => {\n  isQuerying.value = value !== debouncedSearchQuery.value\n})\nconst updateKeyRef = toRef(() => toValue(updateKey))\n\nwatch(\n  [debouncedSearchQuery, updateKeyRef],\n  (_, __, onCleanup) => {\n    let isCleanup = false\n    let cleanupFn: undefined | (() => void)\n    onCleanup(() => {\n      isCleanup = true\n      cleanupFn?.()\n    })\n\n    searcher(debouncedSearchQuery.value, (cb) => (cleanupFn = cb))\n      .catch((error) => {\n        console.error('[AsyncSearchInput] searcher failed', error)\n      })\n      .finally(() => {\n        if (!isCleanup) isQuerying.value = false\n      })\n  },\n  { immediate: true }\n)\n\nfunction handleFocus(event: FocusEvent) {\n  const target = event.target\n  if (target instanceof HTMLInputElement) {\n    target.select()\n  }\n}\n\nfunction handleKeydownEnter(event: KeyboardEvent) {\n  if (event.isComposing) return\n  emit('enter', event)\n}\n</script>\n\n<template>\n  <label\n    :class=\"\n      cn(\n        'group',\n        'rounded-lg bg-secondary-background transition-all duration-150',\n        'flex flex-1 items-center',\n        'border-0 text-base-foreground',\n        'focus-within:ring focus-within:ring-border-default/80',\n        customClass\n      )\n    \"\n  >\n    <i\n      :class=\"\n        cn(\n          'ml-2 size-4 shrink-0 transition-colors duration-150',\n          isQuerying\n            ? 'icon-[lucide--loader-circle] animate-spin'\n            : 'icon-[lucide--search]',\n          searchQuery?.trim() !== ''\n            ? 'text-base-foreground'\n            : 'text-muted-foreground group-focus-within:text-base-foreground group-hover:text-base-foreground'\n        )\n      \"\n    />\n    <input\n      ref=\"inputRef\"\n      v-model=\"searchQuery\"\n      type=\"text\"\n      class=\"mx-2 my-1.5 h-5 w-full min-w-0 border-0 bg-transparent ring-0 outline-0\"\n      :placeholder=\"$t('g.searchPlaceholder', { subject: '' })\"\n      :autofocus\n      @focus=\"handleFocus\"\n      @keydown.enter=\"handleKeydownEnter\"\n    />\n    <button\n      v-if=\"searchQuery.trim().length > 0\"\n      class=\"m-0 flex shrink-0 items-center justify-center border-0 bg-transparent p-0 pr-3 pl-1 text-muted-foreground ring-0 outline-0 transition-all duration-150 hover:scale-108 hover:text-base-foreground\"\n      :aria-label=\"$t('g.clear')\"\n      @click=\"searchQuery = ''\"\n    >\n      <i :class=\"cn('icon-[lucide--delete] size-4 cursor-pointer')\" />\n    </button>\n  </label>\n</template>\n","/**\n * Shared asset sorting utilities\n * Used by both AssetBrowser and FormDropdown\n */\n\nimport type { AssetSortOption } from '../types/filterTypes'\n\n/**\n * Minimal interface for sortable items\n * Works with both AssetItem and FormDropdownItem\n */\nexport interface SortableItem {\n  name: string\n  label?: string\n  created_at?: string | null\n}\n\nfunction getDisplayName(item: SortableItem): string {\n  return item.label ?? item.name\n}\n\n/**\n * Sort items by the specified sort option\n * @param items - Array of sortable items\n * @param sortBy - Sort option from AssetSortOption\n * @returns New sorted array (does not mutate input)\n */\nexport function sortAssets<T extends SortableItem>(\n  items: readonly T[],\n  sortBy: AssetSortOption\n): T[] {\n  if (sortBy === 'default') {\n    return items.slice()\n  }\n\n  const sorted = items.slice()\n\n  switch (sortBy) {\n    case 'name-desc':\n      return sorted.sort((a, b) =>\n        getDisplayName(b).localeCompare(getDisplayName(a), undefined, {\n          numeric: true,\n          sensitivity: 'base'\n        })\n      )\n    case 'recent':\n      return sorted.sort(\n        (a, b) =>\n          new Date(b.created_at ?? 0).getTime() -\n          new Date(a.created_at ?? 0).getTime()\n      )\n    case 'name-asc':\n    default:\n      return sorted.sort((a, b) =>\n        getDisplayName(a).localeCompare(getDisplayName(b), undefined, {\n          numeric: true,\n          sensitivity: 'base'\n        })\n      )\n  }\n}\n","import { createSharedComposable, useAsyncState } from '@vueuse/core'\n\nimport { api } from '@/scripts/api'\n\n/**\n * Format folder name to display name\n * Converts \"upscale_models\" -> \"Upscale Model\"\n * Converts \"loras\" -> \"LoRA\"\n */\nfunction formatDisplayName(folderName: string): string {\n  // Special cases for acronyms and proper nouns\n  const specialCases: Record<string, string> = {\n    loras: 'LoRA',\n    ipadapter: 'IP-Adapter',\n    sams: 'SAM',\n    clip_vision: 'CLIP Vision',\n    animatediff_motion_lora: 'AnimateDiff Motion LoRA',\n    animatediff_models: 'AnimateDiff Model',\n    vae: 'VAE',\n    sam2: 'SAM 2',\n    controlnet: 'ControlNet',\n    gligen: 'GLIGEN'\n  }\n\n  if (specialCases[folderName]) {\n    return specialCases[folderName]\n  }\n\n  return folderName\n    .split('_')\n    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))\n    .join(' ')\n}\n\ninterface ModelTypeOption {\n  name: string // Display name\n  value: string // Actual tag value\n}\n\nconst DISALLOWED_MODEL_TYPES = ['nlf'] as const\n\n/**\n * Composable for fetching and managing model types from the API\n * Uses shared state to ensure data is only fetched once\n */\nexport const useModelTypes = createSharedComposable(() => {\n  const {\n    state: modelTypes,\n    isReady,\n    isLoading,\n    error,\n    execute\n  } = useAsyncState(\n    async (): Promise<ModelTypeOption[]> => {\n      const response = await api.getModelFolders()\n      return response\n        .filter(\n          (folder) =>\n            !DISALLOWED_MODEL_TYPES.includes(\n              folder.name as (typeof DISALLOWED_MODEL_TYPES)[number]\n            )\n        )\n        .map((folder) => ({\n          name: formatDisplayName(folder.name),\n          value: folder.name\n        }))\n        .sort((a, b) => a.name.localeCompare(b.name))\n    },\n    [] as ModelTypeOption[],\n    {\n      immediate: false,\n      onError: (err) => {\n        console.error('Failed to fetch model types:', err)\n      }\n    }\n  )\n\n  async function fetchModelTypes() {\n    if (isReady.value || isLoading.value) return\n    await execute()\n  }\n\n  return {\n    modelTypes,\n    isLoading,\n    error,\n    fetchModelTypes\n  }\n})\n","<template>\n  <div class=\"flex flex-col gap-4 text-sm text-muted-foreground\">\n    <div class=\"flex flex-col gap-2\">\n      <p class=\"m-0\">\n        {{ $t('assetBrowser.modelAssociatedWithLink') }}\n      </p>\n      <div\n        class=\"flex items-center gap-3 rounded-lg bg-secondary-background px-4 py-2\"\n      >\n        <img\n          v-if=\"previewImage\"\n          :src=\"previewImage\"\n          :alt=\"metadata?.filename || metadata?.name || 'Model preview'\"\n          class=\"size-14 shrink-0 rounded-sm object-cover\"\n        />\n        <p class=\"m-0 min-w-0 flex-1 truncate text-base-foreground\">\n          {{ metadata?.filename || metadata?.name }}\n        </p>\n      </div>\n    </div>\n\n    <div\n      v-if=\"isMissingModelResolution\"\n      class=\"flex flex-col gap-2 rounded-lg bg-secondary-background px-4 py-3\"\n    >\n      <i18n-t\n        keypath=\"assetBrowser.missingModelImportWillReplace\"\n        tag=\"p\"\n        class=\"m-0 text-base-foreground\"\n      >\n        <template #model>\n          <span>{{ missingModelName }}</span>\n        </template>\n      </i18n-t>\n      <ul class=\"m-0 list-none space-y-1 p-0\">\n        <li\n          v-for=\"target in replacementTargets\"\n          :key=\"`${target.nodeId}:${target.widgetName}`\"\n          class=\"flex min-w-0 items-center gap-2\"\n        >\n          <span class=\"min-w-0 truncate text-muted-foreground\">\n            {{ target.nodeLabel }}\n          </span>\n          <span class=\"shrink-0 text-muted-foreground\">\n            - {{ target.widgetName }}\n          </span>\n        </li>\n      </ul>\n    </div>\n\n    <!-- Model Type Selection -->\n    <div class=\"flex flex-col gap-2\">\n      <div class=\"flex flex-col gap-1\">\n        <div class=\"flex items-center gap-2\">\n          <label>\n            {{ $t('assetBrowser.modelTypeSelectorLabel') }}\n          </label>\n          <i\n            aria-hidden=\"true\"\n            class=\"icon-[lucide--circle-question-mark] text-muted-foreground\"\n          />\n          <span v-if=\"!isMissingModelResolution\" class=\"text-muted-foreground\">\n            {{ $t('assetBrowser.notSureLeaveAsIs') }}\n          </span>\n        </div>\n      </div>\n      <SingleSelect\n        v-model=\"modelValue\"\n        :label=\"\n          isLoading\n            ? $t('g.loading')\n            : $t('assetBrowser.modelTypeSelectorPlaceholder')\n        \"\n        :options=\"modelTypes\"\n        :disabled=\"isLoading || isMissingModelResolution\"\n        data-attr=\"upload-model-step2-type-selector\"\n      />\n      <i18n-t\n        v-if=\"isMissingModelResolution\"\n        keypath=\"assetBrowser.missingModelImportTypeLocked\"\n        tag=\"span\"\n        class=\"text-muted-foreground\"\n      >\n        <template #type>\n          <span>{{ selectedModelTypeLabel }}</span>\n        </template>\n      </i18n-t>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport SingleSelect from '@/components/ui/single-select/SingleSelect.vue'\nimport { useModelTypes } from '@/platform/assets/composables/useModelTypes'\nimport type { UploadModelDialogContext } from '@/platform/assets/composables/useUploadModelWizard'\nimport type { AssetMetadata } from '@/platform/assets/schemas/assetSchema'\n\nconst { uploadContext } = defineProps<{\n  metadata?: AssetMetadata\n  previewImage?: string\n  uploadContext?: UploadModelDialogContext\n}>()\n\nconst modelValue = defineModel<string | undefined>()\n\nconst { modelTypes, isLoading } = useModelTypes()\n\nconst isMissingModelResolution = computed(\n  () => uploadContext?.kind === 'missing-model-resolution'\n)\nconst missingModelName = computed(() =>\n  uploadContext?.kind === 'missing-model-resolution'\n    ? uploadContext.missingModelName\n    : ''\n)\nconst replacementTargets = computed(() =>\n  uploadContext?.kind === 'missing-model-resolution'\n    ? uploadContext.replacementTargets\n    : []\n)\nconst selectedModelTypeLabel = computed(() => {\n  const value =\n    uploadContext?.kind === 'missing-model-resolution'\n      ? uploadContext.requiredModelType\n      : modelValue.value\n  return (\n    modelTypes.value.find((option) => option.value === value)?.name ?? value\n  )\n})\n</script>\n","<template>\n  <div class=\"flex flex-col gap-4 text-sm text-muted-foreground\">\n    <div class=\"flex flex-col gap-2\">\n      <p class=\"m-0\">\n        {{ $t('assetBrowser.modelAssociatedWithLink') }}\n      </p>\n      <div\n        class=\"flex items-center gap-3 rounded-lg bg-secondary-background px-4 py-2\"\n      >\n        <img\n          v-if=\"previewImage\"\n          :src=\"previewImage\"\n          :alt=\"metadata?.filename || metadata?.name || 'Model preview'\"\n          class=\"size-14 shrink-0 rounded-sm object-cover\"\n        />\n        <p class=\"m-0 min-w-0 flex-1 truncate text-base-foreground\">\n          {{ metadata?.filename || metadata?.name }}\n        </p>\n      </div>\n    </div>\n\n    <div\n      v-if=\"isMissingModelResolution\"\n      class=\"flex flex-col gap-2 rounded-lg bg-secondary-background px-4 py-3\"\n    >\n      <i18n-t\n        keypath=\"assetBrowser.missingModelImportWillReplace\"\n        tag=\"p\"\n        class=\"m-0 text-base-foreground\"\n      >\n        <template #model>\n          <span>{{ missingModelName }}</span>\n        </template>\n      </i18n-t>\n      <ul class=\"m-0 list-none space-y-1 p-0\">\n        <li\n          v-for=\"target in replacementTargets\"\n          :key=\"`${target.nodeId}:${target.widgetName}`\"\n          class=\"flex min-w-0 items-center gap-2\"\n        >\n          <span class=\"min-w-0 truncate text-muted-foreground\">\n            {{ target.nodeLabel }}\n          </span>\n          <span class=\"shrink-0 text-muted-foreground\">\n            - {{ target.widgetName }}\n          </span>\n        </li>\n      </ul>\n    </div>\n\n    <!-- Model Type Selection -->\n    <div class=\"flex flex-col gap-2\">\n      <div class=\"flex flex-col gap-1\">\n        <div class=\"flex items-center gap-2\">\n          <label>\n            {{ $t('assetBrowser.modelTypeSelectorLabel') }}\n          </label>\n          <i\n            aria-hidden=\"true\"\n            class=\"icon-[lucide--circle-question-mark] text-muted-foreground\"\n          />\n          <span v-if=\"!isMissingModelResolution\" class=\"text-muted-foreground\">\n            {{ $t('assetBrowser.notSureLeaveAsIs') }}\n          </span>\n        </div>\n      </div>\n      <SingleSelect\n        v-model=\"modelValue\"\n        :label=\"\n          isLoading\n            ? $t('g.loading')\n            : $t('assetBrowser.modelTypeSelectorPlaceholder')\n        \"\n        :options=\"modelTypes\"\n        :disabled=\"isLoading || isMissingModelResolution\"\n        data-attr=\"upload-model-step2-type-selector\"\n      />\n      <i18n-t\n        v-if=\"isMissingModelResolution\"\n        keypath=\"assetBrowser.missingModelImportTypeLocked\"\n        tag=\"span\"\n        class=\"text-muted-foreground\"\n      >\n        <template #type>\n          <span>{{ selectedModelTypeLabel }}</span>\n        </template>\n      </i18n-t>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport SingleSelect from '@/components/ui/single-select/SingleSelect.vue'\nimport { useModelTypes } from '@/platform/assets/composables/useModelTypes'\nimport type { UploadModelDialogContext } from '@/platform/assets/composables/useUploadModelWizard'\nimport type { AssetMetadata } from '@/platform/assets/schemas/assetSchema'\n\nconst { uploadContext } = defineProps<{\n  metadata?: AssetMetadata\n  previewImage?: string\n  uploadContext?: UploadModelDialogContext\n}>()\n\nconst modelValue = defineModel<string | undefined>()\n\nconst { modelTypes, isLoading } = useModelTypes()\n\nconst isMissingModelResolution = computed(\n  () => uploadC