reviewImage\"\n          :src=\"previewImage\"\n          :alt=\"metadata?.filename || metadata?.name || 'Model preview'\"\n          class=\"size-14 shrink-0 rounded-sm object-cover\"\n        />\n        <div\n          class=\"flex min-w-0 flex-1 flex-col items-start justify-center gap-1\"\n        >\n          <p class=\"m-0 w-full truncate text-base-foreground\">\n            {{ metadata?.filename || metadata?.name }}\n          </p>\n          <p class=\"m-0 text-sm text-muted\">\n            {{ modelType }}\n          </p>\n        </div>\n      </div>\n    </div>\n\n    <!-- Error State -->\n    <div\n      v-else-if=\"result === 'error'\"\n      class=\"flex flex-1 flex-col items-center justify-center gap-6\"\n    >\n      <i\n        aria-hidden=\"true\"\n        class=\"text-error\"\n        :class=\"\n          typeMismatch\n            ? 'icon-[lucide--circle-alert] size-12'\n            : 'icon-[lucide--x-circle] size-16'\n        \"\n      />\n      <div\n        v-if=\"typeMismatch\"\n        class=\"flex max-w-2xl flex-col gap-3 text-center\"\n      >\n        <p class=\"m-0 text-sm font-bold\">\n          {{ $t('assetBrowser.missingModelImportTypeMismatchTitle') }}\n        </p>\n        <i18n-t\n          keypath=\"assetBrowser.missingModelImportTypeMismatchAlreadyImported\"\n          tag=\"p\"\n          class=\"m-0 text-sm text-muted\"\n        >\n          <template #actual>\n            <span>{{ actualModelTypeLabel }}</span>\n          </template>\n        </i18n-t>\n        <i18n-t\n          keypath=\"assetBrowser.missingModelImportTypeMismatchRequired\"\n          tag=\"p\"\n          class=\"m-0 text-sm text-muted\"\n        >\n          <template #required>\n            <span>{{ typeMismatch.requiredModelTypeLabel }}</span>\n          </template>\n        </i18n-t>\n        <i18n-t\n          keypath=\"assetBrowser.missingModelImportTypeMismatchNextAction\"\n          tag=\"p\"\n          class=\"m-0 text-sm text-base-foreground\"\n        >\n          <template #required>\n            <span>{{ typeMismatch.requiredModelTypeLabel }}</span>\n          </template>\n        </i18n-t>\n      </div>\n      <div v-else class=\"text-center\">\n        <p class=\"m-0 text-sm font-bold\">\n          {{ $t('assetBrowser.uploadFailed') }}\n        </p>\n        <p v-if=\"error\" class=\"mb-0 text-sm text-muted\">\n          {{ error }}\n        </p>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport type { AssetMetadata } from '@/platform/assets/schemas/assetSchema'\nimport type { UploadModelTypeMismatch } from '@/platform/assets/composables/useUploadModelWizard'\n\nconst { typeMismatch } = defineProps<{\n  result: 'processing' | 'success' | 'error'\n  error?: string\n  metadata?: AssetMetadata\n  modelType?: string\n  previewImage?: string\n  typeMismatch?: UploadModelTypeMismatch | null\n}>()\n\nconst { t } = useI18n()\nconst isTypeMismatchError = computed(() => typeMismatch != null)\nconst actualModelTypeLabel = computed(\n  () =>\n    typeMismatch?.importedModelTypeLabel ??\n    t('assetBrowser.missingModelImportUnknownType')\n)\n</script>\n","<template>\n  <div\n    :class=\"\n      cn(\n        'flex flex-1 flex-col gap-6 text-sm text-muted-foreground',\n        isTypeMismatchError && 'min-h-full justify-center'\n      )\n    \"\n  >\n    <!-- Processing State (202 async download in progress) -->\n    <div v-if=\"result === 'processing'\" class=\"flex flex-col gap-2\">\n      <p class=\"m-0 font-bold\">\n        {{ $t('assetBrowser.processingModel') }}\n      </p>\n      <p class=\"m-0\">\n        {{ $t('assetBrowser.processingModelDescription') }}\n      </p>\n\n      <div\n        class=\"flex flex-row items-center gap-3 rounded-lg bg-modal-card-background p-4\"\n      >\n        <img\n          v-if=\"previewImage\"\n          :src=\"previewImage\"\n          :alt=\"metadata?.filename || metadata?.name || 'Model preview'\"\n          class=\"size-14 shrink-0 rounded-sm object-cover\"\n        />\n        <div\n          class=\"flex min-w-0 flex-1 flex-col items-start justify-center gap-1\"\n        >\n          <p class=\"m-0 w-full truncate text-base-foreground\">\n            {{ metadata?.filename || metadata?.name }}\n          </p>\n          <p class=\"m-0 text-sm text-muted\">\n            {{ modelType }}\n          </p>\n        </div>\n      </div>\n    </div>\n\n    <!-- Success State -->\n    <div v-else-if=\"result === 'success'\" class=\"flex flex-col gap-2\">\n      <p class=\"m-0 font-bold\">\n        {{ $t('assetBrowser.modelUploaded') }}\n      </p>\n      <p class=\"m-0\">\n        {{ $t('assetBrowser.findInLibrary', { type: modelType }) }}\n      </p>\n\n      <div\n        class=\"flex flex-row items-center gap-3 rounded-lg bg-modal-card-background p-4\"\n      >\n        <img\n          v-if=\"previewImage\"\n          :src=\"previewImage\"\n          :alt=\"metadata?.filename || metadata?.name || 'Model preview'\"\n          class=\"size-14 shrink-0 rounded-sm object-cover\"\n        />\n        <div\n          class=\"flex min-w-0 flex-1 flex-col items-start justify-center gap-1\"\n        >\n          <p class=\"m-0 w-full truncate text-base-foreground\">\n            {{ metadata?.filename || metadata?.name }}\n          </p>\n          <p class=\"m-0 text-sm text-muted\">\n            {{ modelType }}\n          </p>\n        </div>\n      </div>\n    </div>\n\n    <!-- Error State -->\n    <div\n      v-else-if=\"result === 'error'\"\n      class=\"flex flex-1 flex-col items-center justify-center gap-6\"\n    >\n      <i\n        aria-hidden=\"true\"\n        class=\"text-error\"\n        :class=\"\n          typeMismatch\n            ? 'icon-[lucide--circle-alert] size-12'\n            : 'icon-[lucide--x-circle] size-16'\n        \"\n      />\n      <div\n        v-if=\"typeMismatch\"\n        class=\"flex max-w-2xl flex-col gap-3 text-center\"\n      >\n        <p class=\"m-0 text-sm font-bold\">\n          {{ $t('assetBrowser.missingModelImportTypeMismatchTitle') }}\n        </p>\n        <i18n-t\n          keypath=\"assetBrowser.missingModelImportTypeMismatchAlreadyImported\"\n          tag=\"p\"\n          class=\"m-0 text-sm text-muted\"\n        >\n          <template #actual>\n            <span>{{ actualModelTypeLabel }}</span>\n          </template>\n        </i18n-t>\n        <i18n-t\n          keypath=\"assetBrowser.missingModelImportTypeMismatchRequired\"\n          tag=\"p\"\n          class=\"m-0 text-sm text-muted\"\n        >\n          <template #required>\n            <span>{{ typeMismatch.requiredModelTypeLabel }}</span>\n          </template>\n        </i18n-t>\n        <i18n-t\n          keypath=\"assetBrowser.missingModelImportTypeMismatchNextAction\"\n          tag=\"p\"\n          class=\"m-0 text-sm text-base-foreground\"\n        >\n          <template #required>\n            <span>{{ typeMismatch.requiredModelTypeLabel }}</span>\n          </template>\n        </i18n-t>\n      </div>\n      <div v-else class=\"text-center\">\n        <p class=\"m-0 text-sm font-bold\">\n          {{ $t('assetBrowser.uploadFailed') }}\n        </p>\n        <p v-if=\"error\" class=\"mb-0 text-sm text-muted\">\n          {{ error }}\n        </p>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport type { AssetMetadata } from '@/platform/assets/schemas/assetSchema'\nimport type { UploadModelTypeMismatch } from '@/platform/assets/composables/useUploadModelWizard'\n\nconst { typeMismatch } = defineProps<{\n  result: 'processing' | 'success' | 'error'\n  error?: string\n  metadata?: AssetMetadata\n  modelType?: string\n  previewImage?: string\n  typeMismatch?: UploadModelTypeMismatch | null\n}>()\n\nconst { t } = useI18n()\nconst isTypeMismatchError = computed(() => typeMismatch != null)\nconst actualModelTypeLabel = computed(\n  () =>\n    typeMismatch?.importedModelTypeLabel ??\n    t('assetBrowser.missingModelImportUnknownType')\n)\n</script>\n","<template>\n  <div class=\"flex h-full flex-col justify-between gap-6 text-sm\">\n    <div class=\"flex flex-col gap-6\">\n      <div class=\"flex flex-col gap-2\">\n        <p class=\"m-0 text-base-foreground\">\n          {{ $t('assetBrowser.uploadModelDescription1Generic') }}\n        </p>\n        <div class=\"m-0\">\n          <p class=\"m-0 text-muted-foreground\">\n            {{ $t('assetBrowser.uploadModelDescription2Generic') }}\n          </p>\n          <span class=\"mt-2 inline-flex flex-wrap items-center gap-1\">\n            <span class=\"inline-flex items-center gap-1\">\n              <img\n                :src=\"civitaiIcon\"\n                :alt=\"$t('assetBrowser.providerCivitai')\"\n                class=\"size-4\"\n              />\n              <a\n                :href=\"civitaiUrl\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                class=\"text-muted-foreground underline\"\n              >\n                {{ $t('assetBrowser.providerCivitai') }}</a\n              ><span>,</span>\n            </span>\n            <span class=\"inline-flex items-center gap-1\">\n              <img\n                :src=\"huggingFaceIcon\"\n                :alt=\"$t('assetBrowser.providerHuggingFace')\"\n                class=\"size-4\"\n              />\n              <a\n                :href=\"huggingFaceUrl\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                class=\"text-muted-foreground underline\"\n              >\n                {{ $t('assetBrowser.providerHuggingFace') }}\n              </a>\n            </span>\n          </span>\n        </div>\n      </div>\n\n      <div class=\"flex flex-col gap-2\">\n        <Input\n          v-model=\"url\"\n          autofocus\n          :placeholder=\"$t('assetBrowser.genericLinkPlaceholder')\"\n          data-attr=\"upload-model-step1-url-input\"\n        />\n        <p v-if=\"error\" class=\"text-sm text-error\">\n          {{ error }}\n        </p>\n      </div>\n    </div>\n\n    <div class=\"flex flex-col gap-6 text-sm text-muted-foreground\">\n      <div v-if=\"showSecretsHint\">\n        <i18n-t keypath=\"assetBrowser.apiKeyHint\" tag=\"span\">\n          <template #link>\n            <Button\n              variant=\"textonly\"\n              size=\"unset\"\n              class=\"p-0 text-muted-foreground underline\"\n              @click=\"openSecretsSettings\"\n            >\n              {{ $t('assetBrowser.apiKeyHintLink') }}\n            </Button>\n          </template>\n        </i18n-t>\n      </div>\n      <div>\n        {{ $t('assetBrowser.uploadModelHelpFooterText') }}\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\n\nconst { flags } = useFeatureFlags()\nconst settingsDialog = useSettingsDialog()\n\nconst showSecretsHint = computed(() => flags.userSecretsEnabled)\n\nfunction openSecretsSettings() {\n  settingsDialog.show('secrets')\n}\n\nconst props = defineProps<{\n  modelValue: string\n  error?: string\n}>()\n\nconst emit = defineEmits<{\n  'update:modelValue': [value: string]\n}>()\n\nconst url = computed({\n  get: () => props.modelValue,\n  set: (value: string) => emit('update:modelValue', value)\n})\n\nconst civitaiIcon = '/assets/images/civitai.svg'\nconst civitaiUrl = 'https://civitai.com/models'\nconst huggingFaceIcon = '/assets/images/hf-logo.svg'\nconst huggingFaceUrl = 'https://huggingface.co'\n</script>\n","<template>\n  <div class=\"flex h-full flex-col justify-between gap-6 text-sm\">\n    <div class=\"flex flex-col gap-6\">\n      <div class=\"flex flex-col gap-2\">\n        <p class=\"m-0 text-base-foreground\">\n          {{ $t('assetBrowser.uploadModelDescription1Generic') }}\n        </p>\n        <div class=\"m-0\">\n          <p class=\"m-0 text-muted-foreground\">\n            {{ $t('assetBrowser.uploadModelDescription2Generic') }}\n          </p>\n          <span class=\"mt-2 inline-flex flex-wrap items-center gap-1\">\n            <span class=\"inline-flex items-center gap-1\">\n              <img\n                :src=\"civitaiIcon\"\n                :alt=\"$t('assetBrowser.providerCivitai')\"\n                class=\"size-4\"\n              />\n              <a\n                :href=\"civitaiUrl\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                class=\"text-muted-foreground underline\"\n              >\n                {{ $t('assetBrowser.providerCivitai') }}</a\n              ><span>,</span>\n            </span>\n            <span class=\"inline-flex items-center gap-1\">\n              <img\n                :src=\"huggingFaceIcon\"\n                :alt=\"$t('assetBrowser.providerHuggingFace')\"\n                class=\"size-4\"\n              />\n              <a\n                :href=\"huggingFaceUrl\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                class=\"text-muted-foreground underline\"\n              >\n                {{ $t('assetBrowser.providerHuggingFace') }}\n              </a>\n            </span>\n          </span>\n        </div>\n      </div>\n\n      <div class=\"flex flex-col gap-2\">\n        <Input\n          v-model=\"url\"\n          autofocus\n          :placeholder=\"$t('assetBrowser.genericLinkPlaceholder')\"\n          data-attr=\"upload-model-step1-url-input\"\n        />\n        <p v-if=\"error\" class=\"text-sm text-error\">\n          {{ error }}\n        </p>\n      </div>\n    </div>\n\n    <div class=\"flex flex-col gap-6 text-sm text-muted-foreground\">\n      <div v-if=\"showSecretsHint\">\n        <i18n-t keypath=\"assetBrowser.apiKeyHint\" tag=\"span\">\n          <template #link>\n            <Button\n              variant=\"textonly\"\n              size=\"unset\"\n              class=\"p-0 text-muted-foreground underline\"\n              @click=\"openSecretsSettings\"\n            >\n              {{ $t('assetBrowser.apiKeyHintLink') }}\n            </Button>\n          </template>\n        </i18n-t>\n      </div>\n      <div>\n        {{ $t('assetBrowser.uploadModelHelpFooterText') }}\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\n\nconst { flags } = useFeatureFlags()\nconst settingsDialog = useSettingsDialog()\n\nconst showSecretsHint = computed(() => flags.userSecretsEnabled)\n\nfunction openSecretsSettings() {\n  settingsDialog.show('secrets')\n}\n\nconst props = defineProps<{\n  modelValue: string\n  error?: string\n}>()\n\nconst emit = defineEmits<{\n  'update:modelValue': [value: string]\n}>()\n\nconst url = computed({\n  get: () => props.modelValue,\n  set: (value: string) => emit('update:modelValue', value)\n})\n\nconst civitaiIcon = '/assets/images/civitai.svg'\nconst civitaiUrl = 'https://civitai.com/models'\nconst huggingFaceIcon = '/assets/images/hf-logo.svg'\nconst huggingFaceUrl = 'https://huggingface.co'\n</script>\n","import type { ImportSource } from '@/platform/assets/types/importSource'\n\n/**\n * Civitai model import source configuration\n */\nexport const civitaiImportSource: ImportSource = {\n  type: 'civitai',\n  name: 'Civitai',\n  hostnames: ['civitai.com', 'civitai.red']\n}\n","import type { ImportSource } from '@/platform/assets/types/importSource'\n\n/**\n * Hugging Face model import source configuration\n */\nexport const huggingfaceImportSource: ImportSource = {\n  type: 'huggingface',\n  name: 'Hugging Face',\n  hostnames: ['huggingface.co']\n}\n","import type { ImportSource } from '@/platform/assets/types/importSource'\n\n/**\n * Check if a URL belongs to a specific import source\n */\nexport function validateSourceUrl(url: string, source: ImportSource): boolean {\n  try {\n    const hostname = new URL(url).hostname.toLowerCase()\n    return source.hostnames.some(\n      (h) => hostname === h || hostname.endsWith(`.${h}`)\n    )\n  } catch {\n    return false\n  }\n}\n","import type { Ref } from 'vue'\nimport { computed, onScopeDispose, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { st } from '@/i18n'\nimport { civitaiImportSource } from '@/platform/assets/importSources/civitaiImportSource'\nimport { huggingfaceImportSource } from '@/platform/assets/importSources/huggingfaceImportSource'\nimport type {\n  AssetItem,\n  AssetMetadata\n} from '@/platform/assets/schemas/assetSchema'\nimport { assetService } from '@/platform/assets/services/assetService'\nimport type { ImportSource } from '@/platform/assets/types/importSource'\nimport {\n  getAssetFilename,\n  stripModelTypePrefix,\n  toModelTypeTag\n} from '@/platform/assets/utils/assetMetadataUtils'\nimport { validateSourceUrl } from '@/platform/assets/utils/importSourceUtil'\nimport { useAssetDownloadStore } from '@/stores/assetDownloadStore'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport { useModelToNodeStore } from '@/stores/modelToNodeStore'\n\ninterface WizardData {\n  url: string\n  metadata?: AssetMetadata\n  name: string\n  tags: string[]\n  previewImage?: string\n}\n\ninterface ModelTypeOption {\n  name: string\n  value: string\n}\n\nconst MODEL_ROOT_TAG = 'models'\n\nexport interface UploadModelSuccess {\n  filename: string\n  modelType?: string\n  taskId?: string\n  status: 'processing' | 'success'\n}\n\nexport interface UploadModelTypeMismatch {\n  importedModelType?: string\n  importedModelTypeLabel?: string\n  requiredModelType: string\n  requiredModelTypeLabel: string\n}\n\ninterface MissingModelUploadContext {\n  kind: 'missing-model-resolution'\n  missingModelName: string\n  requiredModelType: string\n  replacementTargets: Array<{\n    nodeId: string\n    nodeLabel: string\n    widgetName: string\n  }>\n}\n\nexport type UploadModelDialogContext = MissingModelUploadContext\n\ninterface UploadModelWizardOptions {\n  requiredModelType?: string\n}\n\nexport function useUploadModelWizard(\n  modelTypes: Ref<ModelTypeOption[]>,\n  options: UploadModelWizardOptions = {}\n) {\n  const { t } = useI18n()\n  const { flags } = useFeatureFlags()\n  const assetsStore = useAssetsStore()\n  const assetDownloadStore = useAssetDownloadStore()\n  const modelToNodeStore = useModelToNodeStore()\n  const requiredModelType = options.requiredModelType\n  const currentStep = ref(1)\n  const isFetchingMetadata = ref(false)\n  const isUploading = ref(false)\n  const uploadStatus = ref<'processing' | 'success' | 'error'>()\n  const uploadError = ref('')\n  const uploadTypeMismatch = ref<UploadModelTypeMismatch | null>(null)\n  let stopAsyncWatch: (() => void) | undefined\n  let activeAsyncTaskId: string | undefined\n  let uploadGeneration = 0\n  let disposed = false\n  const isStaleUpload = (generation: number) =>\n    disposed || generation !== uploadGeneration\n  onScopeDispose(() => {\n    disposed = true\n    uploadGeneration++\n    stopAsyncWatch?.()\n  })\n\n  const wizardData = ref<WizardData>({\n    url: '',\n    name: '',\n    tags: []\n  })\n\n  const selectedModelType = ref<string | undefined>(requiredModelType)\n  const resolvedModelType = computed(\n    () => requiredModelType ?? selectedModelType.value\n  )\n\n  const importSources: ImportSource[] = [\n    civitaiImportSource,\n    huggingfaceImportSource\n  ]\n\n  // Detected import source based on URL\n  const detectedSource = computed(() => {\n    const url = wizardData.value.url.trim()\n    if (!url) return null\n    return (\n      importSources.find((source) => validateSourceUrl(url, source)) ?? null\n    )\n  })\n\n  // Clear error when URL changes\n  watch(\n    () => wizardData.value.url,\n    () => {\n      uploadError.value = ''\n      uploadTypeMismatch.value = null\n    }\n  )\n\n  if (requiredModelType) {\n    watch(\n      selectedModelType,\n      (value) => {\n        if (value !== requiredModelType) {\n          selectedModelType.value = requiredModelType\n        }\n      },\n      { immediate: true }\n    )\n  }\n\n  // Validation - only enable Continue when URL matches a supported source\n  const canFetchMetadata = computed(() => {\n    return detectedSource.value !== null\n  })\n\n  const canUploadModel = computed(() => {\n    return !!resolvedModelType.value\n  })\n\n  async function fetchMetadata() {\n    if (!canFetchMetadata.value) return\n\n    // Clean and normalize URL\n    let cleanedUrl = wizardData.value.url.trim()\n    try {\n      cleanedUrl = new URL(encodeURI(cleanedUrl)).toString()\n    } catch {\n      // If URL parsing fails, just use the trimmed input\n    }\n    wizardData.value.url = cleanedUrl\n\n    // Validate URL belongs to a supported import source\n    const source = detectedSource.value\n    if (!source) {\n      const supportedSources = importSources.map((s) => s.name).join(', ')\n      uploadError.value = t('assetBrowser.unsupportedUrlSource', {\n        sources: supportedSources\n      })\n      return\n    }\n\n    isFetchingMetadata.value = true\n    try {\n      const metadata = await assetService.getAssetMetadata(wizardData.value.url)\n\n      // Decode URL-encoded filenames (e.g., Chinese characters)\n      if (metadata.filename) {\n        try {\n          metadata.filename = decodeURIComponent(metadata.filename)\n        } catch {\n          // Keep original if decoding fails\n        }\n      }\n      if (metadata.name) {\n        try {\n          metadata.name = decodeURIComponent(metadata.name)\n        } catch {\n          // Keep original if decoding fails\n        }\n      }\n\n      wizardData.value.metadata = metadata\n\n      // Pre-fill name from metadata\n      wizardData.value.name = metadata.filename || metadata.name || ''\n\n      // Store preview image if available\n      wizardData.value.previewImage = metadata.preview_image\n\n      // Pre-fill model type from metadata tags if available\n      if (requiredModelType) {\n        selectedModelType.value = requiredModelType\n      } else if (metadata.tags && metadata.tags.length > 0) {\n        wizardData.value.tags = metadata.tags\n        // Try to detect model type from tags\n        const typeTag = metadata.tags.find((tag) =>\n          modelTypes.value.some((type) => type.value === tag)\n        )\n        if (typeTag) {\n          selectedModelType.value = typeTag\n        }\n      }\n\n      currentStep.value = 2\n    } catch (error) {\n      console.error('Failed to retrieve metadata:', error)\n      uploadError.value =\n        error instanceof Error\n          ? error.message\n          : st(\n              'assetBrowser.uploadModelFailedToRetrieveMetadata',\n              'Failed to retrieve metadata. Please check the link and try again.'\n            )\n      currentStep.value = 1\n    } finally {\n      isFetchingMetadata.value = false\n    }\n  }\n\n  async function uploadPreviewImage(\n    filename: string\n  ): Promise<{ id: string; createdNew: boolean } | undefined> {\n    if (!wizardData.value.previewImage) return undefined\n\n    try {\n      const baseFilename = filename.split('.')[0]\n      let extension = 'png'\n      const mimeMatch = wizardData.value.previewImage.match(\n        /^data:image\\/([^;]+);/\n      )\n      if (mimeMatch) {\n        extension = mimeMatch[1] === 'jpeg' ? 'jpg' : mimeMatch[1]\n      }\n\n      const previewAsset = await assetService.uploadAssetFromBase64({\n        data: wizardData.value.previewImage,\n        name: `${baseFilename}_preview.${extension}`,\n        tags: ['preview']\n      })\n      return {\n        id: previewAsset.id,\n        createdNew: previewAsset.created_new\n      }\n    } catch (error) {\n      console.error('Failed to upload preview image:', error)\n      return undefined\n    }\n  }\n\n  async function refreshModelCaches(modelType = resolvedModelType.value) {\n    if (!modelType) return\n\n    const providers = modelToNodeStore.getAllNodeProviders(modelType)\n    const results = await Promise.allSettled(\n      providers.map((provider) =>\n        assetsStore.updateModelsForNodeType(provider.nodeDef.name)\n      )\n    )\n    results.forEach((result, index) => {\n      if (result.status === 'rejected') {\n        console.error(\n          `Failed to refresh ${providers[index].nodeDef.name}:`,\n          result.reason\n        )\n      }\n    })\n  }\n\n  function getModelTypeLabel(modelType: string): string {\n    return (\n      modelTypes.value.find((type) => type.value === modelType)?.name ??\n      modelType\n    )\n  }\n\n  function getImportedModelType(asset: AssetItem): string | undefined {\n    const subtypeTags = asset.tags\n      .filter((tag) => tag !== MODEL_ROOT_TAG)\n      .map(stripModelTypePrefix)\n    return (\n      subtypeTags.find((tag) =>\n        modelTypes.value.some((type) => type.value === tag)\n      ) ?? subtypeTags[0]\n    )\n  }\n\n  function blockMismatchedImportedModel(\n    asset: AssetItem,\n    requiredType: string\n  ): boolean {\n    if (asset.tags.map(stripModelTypePrefix).includes(requiredType))\n      return false\n\n    const importedType = getImportedModelType(asset)\n    uploadStatus.value = 'error'\n    uploadError.value = ''\n    uploadTypeMismatch.value = {\n      importedModelType: importedType,\n      importedModelTypeLabel: importedType\n        ? getModelTypeLabel(importedType)\n        : undefined,\n      requiredModelType: requiredType,\n      requiredModelTypeLabel: getModelTypeLabel(requiredType)\n    }\n    return true\n  }\n\n  function watchAsyncUpload(\n    taskId: string,\n    filename: string,\n    modelType: string | undefined\n  ): UploadModelSuccess {\n    uploadStatus.value = 'processing'\n    const uploadSuccess: UploadModelSuccess = {\n      filename,\n      modelType,\n      taskId,\n      status: 'processing'\n    }\n\n    activeAsyncTaskId = taskId\n    const watchState: { resolved: boolean; stop?: () => void } = {\n      resolved: false\n    }\n    const stop = watch(\n      () =>\n        assetDownloadStore.downloadList.find((d) => d.taskId === taskId)\n          ?.status,\n      async (status) => {\n        if (activeAsyncTaskId !== taskId) {\n          watchState.stop?.()\n          return\n        }\n        if (status === 'completed') {\n          watchState.resolved = true\n          uploadStatus.value = 'success'\n          uploadError.value = ''\n          await refreshModelCaches()\n          watchState.stop?.()\n          if (stopAsyncWatch === watchState.stop) stopAsyncWatch = undefined\n          if (activeAsyncTaskId === taskId) activeAsyncTaskId = undefined\n          return\n        }\n        if (\n          status === 'failed' ||\n          status === 'cancellation_pending' ||\n          status === 'cancelled'\n        ) {\n          // Keep watching because an authoritative completion can replace\n          // provisional failure and cancellation states.\n          const download = assetDownloadStore.downloadList.find(\n            (d) => d.taskId === taskId\n          )\n          uploadStatus.value = 'error'\n          uploadError.value =\n            status === 'cancelled' || status === 'cancellation_pending'\n              ? t('electronFileDownload.cancelled')\n              : download?.error ||\n                t('assetBrowser.downloadFailed', {\n                  name: download?.assetName || ''\n                })\n        }\n      },\n      { immediate: true }\n    )\n    watchState.stop = stop\n    if (watchState.resolved) {\n      stop()\n      stopAsyncWatch = undefined\n    } else {\n      stopAsyncWatch = stop\n    }\n    return uploadSuccess\n  }\n\n  async function uploadModel(): Promise<UploadModelSuccess | null> {\n    if (isUploading.value) return null\n    if (!canUploadModel.value) {\n      return null\n    }\n\n    const source = detectedSource.value\n    if (!source) {\n      uploadError.value = t('assetBrowser.noValidSourceDetected')\n      return null\n    }\n\n    isUploading.value = true\n    const generation = ++uploadGeneration\n    stopAsyncWatch?.()\n    stopAsyncWatch = undefined\n    activeAsyncTaskId = undefined\n    uploadTypeMismatch.value = null\n    let uploadSuccess: UploadModelSuccess | null = null\n\n    try {\n      const modelType = resolvedModelType.value\n      const subtypeTag =\n        modelType && flags.supportsModelTypeTags\n          ? toModelTypeTag(modelType)\n          : modelType\n      const tags = subtypeTag ? [MODEL_ROOT_TAG, subtypeTag] : [MODEL_ROOT_TAG]\n      const filename =\n        wizardData.value.metadata?.filename ||\n        wizardData.value.metadata?.name ||\n        'model'\n\n      const preview = await uploadPreviewImage(filename)\n      if (isStaleUpload(generation)) {\n        if (preview?.createdNew) {\n          try {\n            await assetService.deleteAsset(preview.id)\n          } catch (error) {\n            console.error('Failed to clean up stale preview image:', error)\n          }\n        }\n        return null\n      }\n\n      const userMetadata = {\n        source: source.type,\n        source_url: wizardData.value.url,\n        model_type: modelType\n      }\n\n      const result = await assetService.uploadAssetAsync({\n        source_url: wizardData.value.url,\n        tags,\n        user_metadata: userMetadata,\n        preview_id: preview?.id\n      })\n\n      if (result.type === 'async' && result.task.status !== 'completed') {\n        if (modelType) {\n          assetDownloadStore.trackDownload(\n            result.task.task_id,\n            modelType,\n            filename\n          )\n        }\n      }\n\n      if (isStaleUpload(generation)) {\n        if (result.type === 'sync' || result.task.status === 'completed') {\n          await refreshModelCaches(modelType)\n        }\n        return null\n      }\n\n      if (result.type === 'async' && result.task.status !== 'completed') {\n        uploadSuccess = watchAsyncUpload(\n          result.task.task_id,\n          filename,\n          modelType\n        )\n      } else {\n        if (\n          requiredModelType &&\n          result.type === 'sync' &&\n          modelType &&\n          blockMismatchedImportedModel(result.asset, modelType)\n        ) {\n          currentStep.value = 3\n          return null\n        }\n\n        uploadStatus.value = 'success'\n        await refreshModelCaches()\n        if (isStaleUpload(generation)) return null\n        uploadSuccess = {\n          filename:\n            result.type === 'sync' ? getAssetFilename(result.asset) : filename,\n          modelType,\n          status: 'success'\n        }\n      }\n      currentStep.value = 3\n    } catch (error) {\n      if (isStaleUpload(generation)) return null\n      console.error('Failed to upload asset:', error)\n      uploadStatus.value = 'error'\n      uploadError.value =\n        error instanceof Error ? error.message : 'Failed to upload model'\n      currentStep.value = 3\n    } finally {\n      if (!isStaleUpload(generation)) {\n        isUploading.value = false\n      }\n    }\n    return uploadSuccess\n  }\n\n  function goToPreviousStep() {\n    if (currentStep.value > 1) {\n      currentStep.value = currentStep.value - 1\n    }\n  }\n\n  function resetWizard() {\n    uploadGeneration++\n    stopAsyncWatch?.()\n    stopAsyncWatch = undefined\n    activeAsyncTaskId = undefined\n    currentStep.value = 1\n    isFetchingMetadata.value = false\n    isUploading.value = false\n    uploadStatus.value = undefined\n    uploadError.value = ''\n    uploadTypeMismatch.value = null\n    wizardData.value = {\n      url: '',\n      name: '',\n      tags: []\n    }\n    selectedModelType.value = requiredModelType\n  }\n\n  return {\n    // State\n    currentStep,\n    isFetchingMetadata,\n    isUploading,\n    uploadStatus,\n    uploadError,\n    uploadTypeMismatch,\n    wizardData,\n    selectedModelType,\n\n    // Computed\n    canFetchMetadata,\n    canUploadModel,\n    detectedSource,\n\n    // Actions\n    fetchMetadata,\n    uploadModel,\n    goToPreviousStep,\n    resetWizard\n  }\n}\n","<template>\n  <div\n    class=\"upload-model-dialog flex flex-col gap-6 border-t border-border-default p-4 pt-6\"\n  >\n    <!-- Scrollable content area -->\n    <div class=\"min-h-0 flex-auto basis-0 overflow-y-auto\">\n      <!-- Step 1: Enter URL -->\n      <UploadModelUrlInput\n        v-if=\"currentStep === 1\"\n        v-model=\"wizardData.url\"\n        :error=\"uploadError\"\n      />\n\n      <!-- Step 2: Confirm Metadata -->\n      <UploadModelConfirmation\n        v-else-if=\"currentStep === 2\"\n        v-model=\"selectedModelType\"\n        :metadata=\"wizardData.metadata\"\n        :preview-image=\"wizardData.previewImage\"\n        :upload-context=\"uploadContext\"\n      />\n\n      <!-- Step 3: Upload Progress -->\n      <UploadModelProgress\n        v-else-if=\"currentStep === 3 && uploadStatus != null\"\n        :result=\"uploadStatus\"\n        :error=\"uploadError\"\n        :type-mismatch=\"uploadTypeMismatch\"\n        :metadata=\"wizardData.metadata\"\n        :model-type=\"selectedModelType\"\n        :preview-image=\"wizardData.previewImage\"\n      />\n    </div>\n\n    <!-- Navigation Footer - always visible -->\n    <UploadModelFooter\n      class=\"shrink-0\"\n      :current-step=\"currentStep\"\n      :is-fetching-metadata=\"isFetchingMetadata\"\n      :is-uploading=\"isUploading\"\n      :can-fetch-metadata=\"canFetchMetadata\"\n      :can-upload-model=\"canUploadModel\"\n      :upload-status=\"uploadStatus\"\n      :can-import-another=\"!isMissingModelResolution\"\n      @back=\"goToPreviousStep\"\n      @fetch-metadata=\"handleFetchMetadata\"\n      @upload=\"handleUploadModel\"\n      @close=\"handleClose\"\n      @import-another=\"resetWizard\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onMounted } from 'vue'\n\nimport UploadModelConfirmation from '@/platform/assets/components/UploadModelConfirmation.vue'\nimport UploadModelFooter from '@/platform/assets/components/UploadModelFooter.vue'\nimport UploadModelProgress from '@/platform/assets/components/UploadModelProgress.vue'\nimport UploadModelUrlInput from '@/platform/assets/components/UploadModelUrlInput.vue'\nimport { useModelTypes } from '@/platform/assets/composables/useModelTypes'\nimport type {\n  UploadModelDialogContext,\n  UploadModelSuccess\n} from '@/platform/assets/composables/useUploadModelWizard'\nimport { useUploadModelWizard } from '@/platform/assets/composables/useUploadModelWizard'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst dialogStore = useDialogStore()\nconst { modelTypes, fetchModelTypes } = useModelTypes()\n\nconst { uploadContext } = defineProps<{\n  uploadContext?: UploadModelDialogContext\n}>()\n\nconst emit = defineEmits<{\n  'upload-success': [result: UploadModelSuccess]\n}>()\n\nconst isMissingModelResolution = computed(\n  () => uploadContext?.kind === 'missing-model-resolution'\n)\nconst requiredModelType = computed(() =>\n  uploadContext?.kind === 'missing-model-resolution'\n    ? uploadContext.requiredModelType\n    : undefined\n)\n\nconst {\n  currentStep,\n  isFetchingMetadata,\n  isUploading,\n  uploadStatus,\n  uploadError,\n  uploadTypeMismatch,\n  wizardData,\n  selectedModelType,\n  canFetchMetadata,\n  canUploadModel,\n  fetchMetadata,\n  uploadModel,\n  goToPreviousStep,\n  resetWizard\n} = useUploadModelWizard(modelTypes, {\n  requiredModelType: requiredModelType.value\n})\n\nasync function handleFetchMetadata() {\n  await fetchMetadata()\n}\n\nasync function handleUploadModel() {\n  const result = await uploadModel()\n  if (result) {\n    emit('upload-success', result)\n  }\n}\n\nfunction handleClose() {\n  dialogStore.closeDialog({ key: 'upload-model' })\n}\n\nonMounted(() => {\n  fetchModelTypes()\n})\n</script>\n\n<style scoped>\n.upload-model-dialog {\n  width: 90vw;\n  max-width: 800px;\n  height: min(400px, 80vh);\n  max-height: 100%;\n}\n\n@media (min-width: 640px) {\n  .upload-model-dialog {\n    width: auto;\n    min-width: 600px;\n  }\n}\n</style>\n","<template>\n  <div\n    class=\"upload-model-dialog flex flex-col gap-6 border-t border-border-default p-4 pt-6\"\n  >\n    <!-- Scrollable content area -->\n    <div class=\"min-h-0 flex-auto basis-0 overflow-y-auto\">\n      <!-- Step 1: Enter URL -->\n      <UploadModelUrlInput\n        v-if=\"currentStep === 1\"\n        v-model=\"wizardData.url\"\n        :error=\"uploadError\"\n      />\n\n      <!-- Step 2: Confirm Metadata -->\n      <UploadModelConfirmation\n        v-else-if=\"currentStep === 2\"\n        v-model=\"selectedModelType\"\n        :metadata=\"wizardData.metadata\"\n        :preview-image=\"wizardData.previewImage\"\n        :upload-context=\"uploadContext\"\n      />\n\n      <!-- Step 3: Upload Progress -->\n      <UploadModelProgress\n        v-else-if=\"currentStep === 3 && uploadStatus != null\"\n        :result=\"uploadStatus\"\n        :error=\"uploadError\"\n        :type-mismatch=\"uploadTypeMismatch\"\n        :metadata=\"wizardData.metadata\"\n        :model-type=\"selectedModelType\"\n        :preview-image=\"wizardData.previewImage\"\n      />\n    </div>\n\n    <!-- Navigation Footer - always visible -->\n    <UploadModelFooter\n      class=\"shrink-0\"\n      :current-step=\"currentStep\"\n      :is-fetching-metadata=\"isFetchingMetadata\"\n      :is-uploading=\"isUploading\"\n      :can-fetch-metadata=\"canFetchMetadata\"\n      :can-upload-model=\"canUploadModel\"\n      :upload-status=\"uploadStatus\"\n      :can-import-another=\"!isMissingModelResolution\"\n      @back=\"goToPreviousStep\"\n      @fetch-metadata=\"handleFetchMetadata\"\n      @upload=\"handleUploadModel\"\n      @close=\"handleClose\"\n      @import-another=\"resetWizard\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onMounted } from 'vue'\n\nimport UploadModelConfirmation from '@/platform/assets/components/UploadModelConfirmation.vue'\nimport UploadModelFooter from '@/platform/assets/components/UploadModelFooter.vue'\nimport UploadModelProgress from '@/platform/assets/components/UploadModelProgress.vue'\nimport UploadModelUrlInput from '@/platform/assets/components/UploadModelUrlInput.vue'\nimport { useModelTypes } from '@/platform/assets/composables/useModelTypes'\nimport type {\n  UploadModelDialogContext,\n  UploadModelSuccess\n} from '@/platform/assets/composables/useUploadModelWizard'\nimport { useUploadModelWizard } from '@/platform/assets/composables/useUploadModelWizard'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst dialogStore = useDialogStore()\nconst { modelTypes, fetchModelTypes } = useModelTypes()\n\nconst { uploadContext } = defineProps<{\n  uploadContext?: UploadModelDialogContext\n}>()\n\nconst emit = defineEmits<{\n  'upload-success': [result: UploadModelSuccess]\n}>()\n\nconst isMissingModelResolution = computed(\n  () => uploadContext?.kind === 'missing-model-resolution'\n)\nconst requiredModelType = computed(() =>\n  uploadContext?.kind === 'missing-model-resolution'\n    ? uploadContext.requiredModelType\n    : undefined\n)\n\nconst {\n  currentStep,\n  isFetchingMetadata,\n  isUploading,\n  uploadStatus,\n  uploadError,\n  uploadTypeMismatch,\n  wizardData,\n  selectedModelType,\n  canFetchMetadata,\n  canUploadModel,\n  fetchMetadata,\n  uploadModel,\n  goToPreviousStep,\n  resetWizard\n} = useUploadModelWizard(modelTypes, {\n  requiredModelType: requiredModelType.value\n})\n\nasync function handleFetchMetadata() {\n  await fetchMetadata()\n}\n\nasync function handleUploadModel() {\n  const result = await uploadModel()\n  if (result) {\n    emit('upload-success', result)\n  }\n}\n\nfunction handleClose() {\n  dialogStore.closeDialog({ key: 'upload-model' })\n}\n\nonMounted(() => {\n  fetchModelTypes()\n})\n</script>\n\n<style scoped>\n.upload-model-dialog {\n  width: 90vw;\n  max-width: 800px;\n  height: min(400px, 80vh);\n  max-height: 100%;\n}\n\n@media (min-width: 640px) {\n  .upload-model-dialog {\n    width: auto;\n    min-width: 600px;\n  }\n}\n</style>\n","<template>\n  <div class=\"flex items-center gap-2 p-4 font-bold\">\n    <span>{{ $t('assetBrowser.uploadModelGeneric') }}</span>\n    <span\n      class=\"rounded-full bg-white px-1.5 py-0 font-inter text-2xs font-semibold text-black uppercase\"\n    >\n      {{ $t('g.beta') }}\n    </span>\n  </div>\n</template>\n","<template>\n  <div\n    class=\"flex flex-1 flex-col items-center justify-center text-base text-muted-foreground\"\n  >\n    <p class=\"m-0 max-w-md\">\n      {{ $t('assetBrowser.upgradeFeatureDescription') }}\n    </p>\n  </div>\n</template>\n","<template>\n  <div class=\"flex w-full flex-wrap justify-end gap-2\">\n    <Button variant=\"textonly\" @click=\"emit('close')\">{{\n      $t('g.close')\n    }}</Button>\n    <Button variant=\"secondary\" @click=\"emit('subscribe')\">\n      {{ $t('subscription.required.subscribe') }}\n    </Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\n\nconst emit = defineEmits<{\n  close: []\n  subscribe: []\n}>()\n</script>\n","<template>\n  <div class=\"flex w-full flex-wrap justify-end gap-2\">\n    <Button variant=\"textonly\" @click=\"emit('close')\">{{\n      $t('g.close')\n    }}</Button>\n    <Button variant=\"secondary\" @click=\"emit('subscribe')\">\n      {{ $t('subscription.required.subscribe') }}\n    </Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\n\nconst emit = defineEmits<{\n  close: []\n  subscribe: []\n}>()\n</script>\n","<template>\n  <div\n    class=\"flex w-auto max-w-[min(500px,90vw)] flex-col justify-between gap-10 border-t border-border-default p-4\"\n  >\n    <UploadModelUpgradeModalBody />\n\n    <UploadModelUpgradeModalFooter\n      @close=\"handleClose\"\n      @subscribe=\"handleSubscribe\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport UploadModelUpgradeModalBody from '@/platform/assets/components/UploadModelUpgradeModalBody.vue'\nimport UploadModelUpgradeModalFooter from '@/platform/assets/components/UploadModelUpgradeModalFooter.vue'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst dialogStore = useDialogStore()\nconst { showSubscriptionDialog } = useBillingContext()\n\nfunction handleClose() {\n  dialogStore.closeDialog({ key: 'upload-model-upgrade' })\n}\n\nfunction handleSubscribe() {\n  showSubscriptionDialog({ reason: 'upload_model_upgrade' })\n}\n</script>\n","<template>\n  <div\n    class=\"flex w-auto max-w-[min(500px,90vw)] flex-col justify-between gap-10 border-t border-border-default p-4\"\n  >\n    <UploadModelUpgradeModalBody />\n\n    <UploadModelUpgradeModalFooter\n      @close=\"handleClose\"\n      @subscribe=\"handleSubscribe\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport UploadModelUpgradeModalBody from '@/platform/assets/components/UploadModelUpgradeModalBody.vue'\nimport UploadModelUpgradeModalFooter from '@/platform/assets/components/UploadModelUpgradeModalFooter.vue'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst dialogStore = useDialogStore()\nconst { showSubscriptionDialog } = useBillingContext()\n\nfunction handleClose() {\n  dialogStore.closeDialog({ key: 'upload-model-upgrade' })\n}\n\nfunction handleSubscribe() {\n  showSubscriptionDialog({ reason: 'upload_model_upgrade' })\n}\n</script>\n","<template>\n  <div class=\"flex items-center gap-2 p-4 font-bold\">\n    <span>{{ $t('assetBrowser.upgradeToUnlockFeature') }}</span>\n  </div>\n</template>\n","import { computed } from 'vue'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport UploadModelDialog from '@/platform/assets/components/UploadModelDialog.vue'\nimport UploadModelDialogHeader from '@/platform/assets/components/UploadModelDialogHeader.vue'\nimport type {\n  UploadModelDialogContext,\n  UploadModelSuccess\n} from '@/platform/assets/composables/useUploadModelWizard'\nimport UploadModelUpgradeModal from '@/platform/assets/components/UploadModelUpgradeModal.vue'\nimport UploadModelUpgradeModalHeader from '@/platform/assets/components/UploadModelUpgradeModalHeader.vue'\nimport { useDialogStore } from '@/stores/dialogStore'\n\ntype UploadModelContextResolver = () => UploadModelDialogContext | undefined\n\nconst uploadDialogComponentProps = {\n  flush: true,\n  size: 'fit'\n} as const\n\nexport function useModelUpload(\n  onUploadSuccess?: (result: UploadModelSuccess) => Promise<unknown> | void,\n  uploadContext?: UploadModelDialogContext | UploadModelContextResolver\n) {\n  const dialogStore = useDialogStore()\n  const { flags } = useFeatureFlags()\n  const isUploadButtonEnabled = computed(() => flags.modelUploadButtonEnabled)\n\n  function resolveUploadContext() {\n    return typeof uploadContext === 'function' ? uploadContext() : uploadContext\n  }\n\n  function showUploadDialog() {\n    if (!flags.privateModelsEnabled) {\n      dialogStore.showDialog({\n        key: 'upload-model-upgrade',\n        headerComponent: UploadModelUpgradeModalHeader,\n        component: UploadModelUpgradeModal,\n        dialogComponentProps: uploadDialogComponentProps\n      })\n    } else {\n      dialogStore.showDialog({\n        key: 'upload-model',\n        headerComponent: UploadModelDialogHeader,\n        component: UploadModelDialog,\n        props: {\n          uploadContext: resolveUploadContext(),\n          onUploadSuccess: async (result: UploadModelSuccess) => {\n            await onUploadSuccess?.(result)\n          }\n        },\n        dialogComponentProps: uploadDialogComponentProps\n      })\n    }\n  }\n  return { isUploadButtonEnabled, showUploadDialog }\n}\n","import { uniqWith } from 'es-toolkit'\nimport { computed, toValue } from 'vue'\nimport type { MaybeRefOrGetter } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { SelectOption } from '@/components/ui/select/types'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport type { OwnershipFilterOption } from '@/platform/assets/types/filterTypes'\nimport { getAssetBaseModels } from '@/platform/assets/utils/assetMetadataUtils'\n\n/**\n * Composable that extracts available filter options from asset data\n * Provides reactive computed properties for file formats, base models, and ownership\n */\nexport function useAssetFilterOptions(assets: MaybeRefOrGetter<AssetItem[]>) {\n  const { t } = useI18n()\n\n  const ownershipOptions = computed<OwnershipFilterOption[]>(() => [\n    { name: t('assetBrowser.ownershipAll'), value: 'all' },\n    { name: t('assetBrowser.ownershipMyModels'), value: 'my-models' },\n    { name: t('assetBrowser.ownershipPublicModels'), value: 'public-models' }\n  ])\n  /**\n   * Extract unique file formats from asset names\n   * Returns sorted SelectOption array with extensions\n   */\n  const availableFileFormats = computed<SelectOption[]>(() => {\n    const assetList = toValue(assets)\n    const extensions = assetList\n      .map((asset) => {\n        const extension = asset.name.split('.').pop()\n        return extension && extension !== asset.name ? extension : null\n      })\n      .filter((extension): extension is string => extension !== null)\n\n    const uniqueExtensions = uniqWith(extensions, (a, b) => a === b)\n\n    return uniqueExtensions.sort().map((format) => ({\n      name: `.${format}`,\n      value: format\n    }))\n  })\n\n  /**\n   * Extract unique base models from asset user metadata\n   * Returns sorted SelectOption array with base model names\n   */\n  const availableBaseModels = computed<SelectOption[]>(() => {\n    const assetList = toValue(assets)\n    const models = assetList.flatMap((asset) => getAssetBaseModels(asset))\n\n    const uniqueModels = uniqWith(models, (a, b) => a === b)\n\n    return uniqueModels.sort().map((model) => ({\n      name: model,\n      value: model\n    }))\n  })\n\n  return {\n    availableFileFormats,\n    availableBaseModels,\n    ownershipOptions\n  }\n}\n","import type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport type { OwnershipOption } from '@/platform/assets/types/filterTypes'\nimport {\n  getAssetBaseModels,\n  getAssetCategories\n} from '@/platform/assets/utils/assetMetadataUtils'\n\nexport function filterByCategory(category: string, modelTypeMode: boolean) {\n  return (asset: AssetItem) => {\n    if (category === 'all') return true\n    return getAssetCategories(asset, modelTypeMode).includes(category)\n  }\n}\n\nexport function filterByFileFormats(formats: string[]) {\n  return (asset: AssetItem) => {\n    if (formats.length === 0) return true\n    const formatSet = new Set(formats)\n    const extension = asset.name.split('.').pop()?.toLowerCase()\n    return extension ? formatSet.has(extension) : false\n  }\n}\n\nexport function filterByBaseModels(models: string[] | Set<string>) {\n  const modelSet = models instanceof Set ? models : new Set(models)\n  return (asset: AssetItem) => {\n    if (modelSet.size === 0) return true\n    const assetBaseModels = getAssetBaseModels(asset)\n    return assetBaseModels.some((model) => modelSet.has(model))\n  }\n}\n\nexport function filterByOwnership(ownership: OwnershipOption) {\n  return (asset: AssetItem) => {\n    if (ownership === 'all') return true\n    // is_immutable is optional; an asset omitting it counts as owned so it\n    // never vanishes from both ownership views.\n    if (ownership === 'my-models') return asset.is_immutable !== true\n    return asset.is_immutable === true\n  }\n}\n\nexport function filterItemByOwnership<T extends { is_immutable?: boolean }>(\n  items: T[],\n  ownership: OwnershipOption\n): T[] {\n  if (ownership === 'all') return items\n  if (ownership === 'public-models') {\n    return items.filter((item) => item.is_immutable === true)\n  }\n  return items.filter((item) => item.is_immutable !== true)\n}\n\nexport function filterItemByBaseModels<T extends { base_models?: string[] }>(\n  items: T[],\n  selectedModels: Set<string>\n): T[] {\n  if (selectedModels.size === 0) return items\n  return items.filter((item) =>\n    item.base_models?.some((model) => selectedModels.has(model))\n  )\n}\n","import type { SerializedNodeId } from '@/types/nodeId'\n\nexport type OutputKeyParts = {\n  nodeId?: SerializedNodeId | null\n  subfolder?: string | null\n  filename?: string | null\n}\n\nexport function getOutputKey({\n  nodeId,\n  subfolder,\n  filename\n}: OutputKeyParts): string | null {\n  if (nodeId == null || subfolder == null || !filename) {\n    return null\n  }\n\n  return JSON.stringify([String(nodeId), subfolder, filename])\n}\n","import type { OutputAssetMetadata } from '@/platform/assets/schemas/assetMetadataSchema'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport { isCloud } from '@/platform/distribution/types'\nimport type { JobOutputAsset } from '@/platform/remote/comfyui/jobs/jobTypes'\nimport { getOutputKey } from '@/platform/assets/utils/outputKeyUtil'\nimport {\n  getJobAssets,\n  getJobDetail,\n  getPreviewableOutputsFromJobDetail\n} from '@/services/jobOutputCache'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport { resultItemPreviewUrl, resultItemUrl } from '@/utils/resultItemUrl'\n\ntype OutputAssetMapOptions = {\n  jobId: string\n  outputs: readonly AugmentedResultItem[]\n  createdAt?: string\n  executionTimeInSeconds?: number\n  workflow?: OutputAssetMetadata['workflow']\n  excludeOutputKey?: string\n}\n\ntype ResolveOutputAssetItemsOptions = {\n  createdAt?: string\n  excludeOutputKey?: string\n}\n\nfunction shouldLoadFullOutputs(\n  outputCount: OutputAssetMetadata['outputCount'],\n  outputsLength: number\n): boolean {\n  return (\n    typeof outputCount === 'number' &&\n    outputCount > 1 &&\n    outputsLength < outputCount\n  )\n}\n\n/**\n * Maps a job's outputs to AssetItems with ids derived from the composite\n * `[nodeId, subfolder, filename]` key. Records sharing a composite key are\n * dropped after the first to keep `:key` unique in VirtualGrid — colliding\n * ids cause Vue to reuse one DOM node and visibly duplicate the asset on\n * scroll.\n *\n * The dedupe key ignores `type`/`mediaType`/`format`/`frame_rate` because\n * those fields don't appear in `AssetItem.id`, so widening the key would\n * just let the collision propagate. The kept copy is the first one seen;\n * callers that reverse the input (e.g. `resolveOutputAssetItems`) retain\n * the last record in the API's original order.\n */\nfunction mapOutputsToAssetItems({\n  jobId,\n  outputs,\n  createdAt,\n  executionTimeInSeconds,\n  workflow,\n  excludeOutputKey\n}: OutputAssetMapOptions): AssetItem[] {\n  const createdAtValue = createdAt ?? new Date().toISOString()\n  const seenOutputKeys = new Set<string>()\n\n  return outputs.reduce<AssetItem[]>((items, output) => {\n    const outputKey = getOutputKey(output)\n    if (!output.filename || !outputKey || outputKey === excludeOutputKey) {\n      return items\n    }\n    if (seenOutputKeys.has(outputKey)) {\n      return items\n    }\n    seenOutputKeys.add(outputKey)\n\n    items.push({\n      id: output.assetId || `${jobId}-${outputKey}`,\n      name: output.filename,\n      display_name: output.display_name,\n      size: 0,\n      created_at: createdAtValue,\n      updated_at: createdAtValue,\n      tags: ['output'],\n      thumbnail_url: resultItemPreviewUrl(output),\n      preview_url: resultItemUrl(output),\n      user_metadata: {\n        jobId,\n        nodeId: output.nodeId,\n        subfolder: output.subfolder,\n        executionTimeInSeconds,\n        workflow\n      }\n    })\n\n    return items\n  }, [])\n}\n\n/**\n * Overlays a resolved job asset onto a synthesized output item, linking it to\n * the asset system: the placeholder `<jobId>-<outputKey>` id becomes the real\n * asset id, and size/mime/preview are filled from the endpoint.\n *\n * `user_metadata` is left untouched. Its `nodeId` and `subfolder` come from\n * the same output entry and are read back as a pair — `useOutputStacks` rebuilds\n * `getOutputKey({ nodeId, subfolder, filename })` to exclude the output already\n * on screen — so overwriting only `nodeId` with the endpoint's (hash-correlated,\n * possibly disagreeing) `node_id` would describe an output that does not exist.\n * The endpoint's `node_id` is used to disambiguate matches instead, not to\n * relabel an item whose own `nodeId` is already required to be present.\n *\n * The endpoint's `hash` is deliberately not copied: downstream\n * `getAssetUrlFilename` treats `hash` as the storage filename, which the\n * endpoint's (`blake3:`-prefixed) value is not. The synthesized\n * `thumbnail_url` wins over the asset's `preview_url` because it carries the\n * resolution-capped `res=` variant; the asset value is the unbounded original.\n */\nfunction overlayJobAsset(item: AssetItem, asset: JobOutputAsset): AssetItem {\n  return {\n    ...item,\n    id: asset.id,\n    size: asset.size ?? item.size,\n    mime_type: asset.mime_type ?? item.mime_type,\n    preview_url: asset.preview_url ?? item.preview_url,\n    thumbnail_url: item.thumbnail_url ?? asset.preview_url ?? undefined\n  }\n}\n\n/**\n * Composite `(filename, node id)` key. The node id is stringified because the\n * output side carries a `SerializedNodeId` (`string | number`) while the\n * endpoint always sends a string, and `9` must pair with `'9'`.\n */\nfunction nodeScopedName(name: string, nodeId: unknown): string | null {\n  return typeof nodeId === 'string' || typeof nodeId === 'number'\n    ? JSON.stringify([name, String(nodeId)])\n    : null\n}\n\n/**\n * Indexes items and assets under a shared key and returns a lookup that pairs\n * them only when the key identifies exactly one of each. A null key (the field\n * it needs is absent) is never indexed, so it can never pair.\n */\nfunction createUniquePairing(\n  items: readonly AssetItem[],\n  jobAssets: readonly JobOutputAsset[],\n  keyOfItem: (item: AssetItem) => string | null,\n  keyOfAsset: (asset: JobOutputAsset) => string | null\n): (key: string | null) => JobOutputAsset | null {\n  const assetsByKey = new Map<string, JobOutputAsset[]>()\n  for (const asset of jobAssets) {\n    const key = keyOfAsset(asset)\n    if (key === null) continue\n    const existing = assetsByKey.get(key)\n    if (existing) {\n      existing.push(asset)\n    } else {\n      assetsByKey.set(key, [asset])\n    }\n  }\n\n  const itemCounts = new Map<string, number>()\n  for (const item of items) {\n    const key = keyOfItem(item)\n    if (key === null) continue\n    itemCounts.set(key, (itemCounts.get(key) ?? 0) + 1)\n  }\n\n  return (key) => {\n    if (key === null) return null\n    const candidates = assetsByKey.get(key)\n    return candidates?.length === 1 && itemCounts.get(key) === 1\n      ? candidates[0]\n      : null\n  }\n}\n\n/**\n * Resolves persisted job outputs to real asset entities via\n * GET /api/jobs/{job_id}/assets, matching by filename (the stable identifier\n * across the history and asset id spaces). Cloud-only; degrades to the\n * unresolved items when the endpoint returns nothing (e.g. not yet deployed).\n *\n * A filename duplicated on either side — among the outputs or among the\n * returned assets — falls back to `(filename, node_id)`, which separates the\n * common collision of one filename written by two different nodes. An output\n * still ambiguous under that pair, or whose asset carries no `node_id`, is\n * left unresolved: `zJobOutputAsset` carries no subfolder and the endpoint's\n * ordering is unspecified, so nothing else pairs duplicates reliably, and a\n * wrong pairing would render one file's preview under another's identity.\n */\nasync function enrichWithJobAssets(\n  jobId: string,\n  items: AssetItem[]\n): Promise<AssetItem[]> {\n  if (!items.length) return items\n\n  let jobAssets: JobOutputAsset[]\n  try {\n    jobAssets = await getJobAssets(jobId)\n  } catch (error) {\n    console.error(`Failed to enrich job ${jobId} with assets:`, error)\n    return items\n  }\n  if (!jobAssets.length) return items\n\n  const matchByName = createUniquePairing(\n    items,\n    jobAssets,\n    (item) => item.name,\n    (asset) => asset.name\n  )\n  const matchByNodeScopedName = createUniquePairing(\n    items,\n    jobAssets,\n    (item) => nodeScopedName(item.name, item.user_metadata?.nodeId),\n    (asset) => nodeScopedName(asset.name, asset.node_id)\n  )\n\n  return items.map((item) => {\n    const match =\n      matchByName(item.name) ??\n      matchByNodeScopedName(\n        nodeScopedName(item.name, item.user_metadata?.nodeId)\n      )\n    return match ? overlayJobAsset(item, match) : item\n  })\n}\n\nexport async function resolveOutputAssetItems(\n  metadata: OutputAssetMetadata,\n  { createdAt, excludeOutputKey }: ResolveOutputAssetItemsOptions = {}\n): Promise<AssetItem[]> {\n  let outputsToDisplay = metadata.allOutputs ?? []\n  if (shouldLoadFullOutputs(metadata.outputCount, outputsToDisplay.len